from PIL import Image
def box(f, xcard, ytop, ybot, tag):
    im=Image.open(f).convert('RGB'); px=im.load()
    card=px[xcard,ytop]
    # find the notes field: scan column x=xcard for contiguous run that differs from card fill and is not a button row
    ys=[]
    for y in range(ybot[0],ybot[1]):
        p=px[xcard,y]
        if max(abs(p[i]-card[i]) for i in range(3))>4: ys.append(y)
    # group
    groups=[]; 
    for y in ys:
        if groups and y-groups[-1][-1]<=1: groups[-1].append(y)
        else: groups.append([y])
    print(tag, im.size, "cardfill", card, "runs:", [(g[0],g[-1],g[-1]-g[0]+1) for g in groups if len(g)>2])
